using System.ComponentModel.DataAnnotations; using System.ComponentModel.DataAnnotations.Schema; using LibrarySystem.Domain.Catalog; using Microsoft.EntityFrameworkCore;
namespace LibrarySystem.Infrastructure.Catalog;
[Table("InventorySessions")] public sealed class InventorySession { [Key] public long Id{get;set;} [Required,MaxLength(200)] public required string Name{get;set;} public InventorySessionStatus Status{get;set;}=InventorySessionStatus.Open; [Precision(0)] public DateTime StartedAtUtc{get;set;}=DateTime.UtcNow; [Precision(0)] public DateTime? CompletedAtUtc{get;set;} [MaxLength(450)] public string? CreatedByUserId{get;set;} public ICollection<InventoryExpectedCopy> ExpectedCopies{get;set;}=[]; public ICollection<InventoryScan> Scans{get;set;}=[]; }
[Table("InventoryExpectedCopies"),Index(nameof(InventorySessionId),nameof(BookCopyId),IsUnique=true)] public sealed class InventoryExpectedCopy { [Key] public long Id{get;set;} public long InventorySessionId{get;set;} [ForeignKey(nameof(InventorySessionId)),DeleteBehavior(DeleteBehavior.Restrict)] public required InventorySession InventorySession{get;set;} public long BookCopyId{get;set;} [ForeignKey(nameof(BookCopyId)),DeleteBehavior(DeleteBehavior.Restrict)] public required BookCopy BookCopy{get;set;} }
[Table("InventoryScans"),Index(nameof(InventorySessionId),nameof(BookCopyId),IsUnique=true)] public sealed class InventoryScan { [Key] public long Id{get;set;} public long InventorySessionId{get;set;} [ForeignKey(nameof(InventorySessionId)),DeleteBehavior(DeleteBehavior.Restrict)] public required InventorySession InventorySession{get;set;} public long BookCopyId{get;set;} [ForeignKey(nameof(BookCopyId)),DeleteBehavior(DeleteBehavior.Restrict)] public required BookCopy BookCopy{get;set;} [Precision(0)] public DateTime FoundAtUtc{get;set;}=DateTime.UtcNow; [MaxLength(450)] public string? FoundByUserId{get;set;} }
[Table("CopyWithdrawals"),Index(nameof(BookCopyId),IsUnique=true)] public sealed class CopyWithdrawal { [Key] public long Id{get;set;} public long BookCopyId{get;set;} [ForeignKey(nameof(BookCopyId)),DeleteBehavior(DeleteBehavior.Restrict)] public required BookCopy BookCopy{get;set;} [Required,MaxLength(500)] public required string Reason{get;set;} [Precision(0)] public DateTime WithdrawnAtUtc{get;set;}=DateTime.UtcNow; [MaxLength(450)] public string? ActorUserId{get;set;} }
